var field = AppKit.Search("Search commands", query => Filter(query), 460, null, "⌘K");

var list = new StackPanel { Spacing = 1 };
foreach (var group in commands.GroupBy(command => command.Group))
{
    list.Children.Add(AppKit.Caption(group.Key));
    foreach (var command in group)
    {
        list.Children.Add(AppKit.Pressable(row: command, selected: index == active, run: command.Run));
    }
}

var panel = AppKit.Floating(new StackPanel
{
    Spacing = 8,
    Children = { field, AppKit.Divider(), list, AppKit.Divider(), AppKit.KeycapHint("↑ ↓ move  ↵ run  esc close") }
}, 12, 16, 480);

var layer = new Panel { Children = { AppKit.Pressable(scrim, Close), panel } };
return AppKit.Screen(layer, 520);
